using System.IO;
using System.Text.Json;
using Liuzhuan;
using Liuzhuan.Models;
using Liuzhuan.Services;
var root=Path.GetFullPath(Path.Combine(args.Length>0?args[0]:"F:/appdata/Temp/liuzhuan-m57-checks","project-staging-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(root);typeof(App).GetProperty(nameof(App.DataDir))!.SetValue(null,root);Liuzhuan.Utils.Logger.Init(root);int checks=0;
void Check(bool value,string name){if(!value)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
async Task Reject(Func<Task> action,string name){bool rejected=false;try{await action();}catch(Exception ex)when(ex is IOException or InvalidOperationException or ArgumentException){rejected=true;}Check(rejected,name);}
string Package(bool complete){var id=Guid.NewGuid().ToString("D");var dir=Path.Combine(root,"project-imports",id);Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"binding.json"),JsonSerializer.Serialize(new{Format="LiuzhuanProjectPackage",PackageId=id,Fingerprint=new string('A',64),Complete=complete}));return id;}
string Payload(string package,string text){var dir=Path.Combine(root,"project-imports",package,"files",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var path=Path.Combine(dir,"synthetic.bin");File.WriteAllText(path,text);return path;}
var complete=Package(true);var incomplete=Package(false);var live=Payload(complete,"live");var undo=Payload(complete,"undo");var transfer=Payload(complete,"transfer");var unused=Payload(complete,"unused");var partial=Payload(incomplete,"partial");var transferDir=Path.Combine(root,"transfers-v1");Directory.CreateDirectory(transferDir);File.WriteAllText(Path.Combine(transferDir,"task.json"),JsonSerializer.Serialize(new{Path=transfer}));
using var store=new DataStore(root);store.Add(new MaterialItem{Id="live",Type=MaterialType.Other,FilePath=live,DisplayName="live"});store.Add(new MaterialItem{Id="undo",Type=MaterialType.Other,FilePath=undo,DisplayName="undo"});store.Remove("undo");await store.FlushAsync();
var preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));Check(preview.Complete&&preview.Packages==2,"staging inspection validates two controlled packages");Check(preview.Files.Length==2&&preview.Files.Any(x=>x.Path==unused)&&preview.Files.Any(x=>x.Path==partial),"only unreferenced complete and incomplete payloads are candidates");Check(preview.ReferencedBytes==4+4+8&&preview.PreparedBytes==6&&preview.IncompleteBytes==7,"logical occupancy separates live, Undo, transfer, complete and incomplete bytes");
await Reject(()=>Task.Run(()=>ProjectStagingService.Recycle(store,preview,new[]{live})),"indexed payload is never accepted as a recycle candidate");
using(ProjectStagingService.AcquirePreparationLease(root)){await Reject(async()=>{await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));},"inspection cannot race an active project preparation or import lease");}
store.Add(new MaterialItem{Type=MaterialType.Text,TextContent="advance-sequence"});await Reject(()=>Task.Run(()=>ProjectStagingService.Recycle(store,preview,new[]{unused})),"library changes invalidate the preview before moving any files");preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));
File.AppendAllText(unused,"changed");await Reject(()=>Task.Run(()=>ProjectStagingService.Recycle(store,preview,new[]{unused})),"payload changes invalidate the move before commit");preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));
var binding=Path.Combine(root,"project-imports",complete,"binding.json");var bindingBytes=File.ReadAllBytes(binding);var payloadBytes=File.ReadAllBytes(unused);Check(ProjectStagingService.Recycle(store,preview,new[]{unused})==1&&!File.Exists(unused),"explicit recycle moves one validated unreferenced payload");Check(File.ReadAllBytes(binding).SequenceEqual(bindingBytes)&&File.Exists(live)&&File.Exists(undo)&&File.Exists(transfer),"recycle leaves bindings and all protected source files untouched");Check(await ProjectStagingService.RestoreLatestAsync(root)==1&&File.ReadAllBytes(unused).SequenceEqual(payloadBytes),"restore brings back the same payload bytes");
preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));ProjectStagingService.Recycle(store,preview,new[]{unused});File.WriteAllText(unused,"new-owner-file");Check(await ProjectStagingService.RestoreLatestAsync(root)==0&&File.ReadAllText(unused)=="new-owner-file","restore never overwrites an already existing payload");Check(Directory.EnumerateFiles(Path.Combine(root,"project-staging-trash-v1"),"*",SearchOption.AllDirectories).Any(x=>Path.GetFileName(x)!="manifest.json"),"blocked restore retains the recycled file");
preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));Check(ProjectStagingService.Recycle(store,preview,new[]{partial})==1&&File.Exists(Path.Combine(root,"project-imports",incomplete,"binding.json")),"explicitly abandoned incomplete payload can move while its binding is retained");
File.WriteAllText(binding,"{bad-binding");preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));Check(!preview.Complete&&File.Exists(live)&&File.Exists(undo),"bad package binding blocks all recycle and preserves sources");File.WriteAllBytes(binding,bindingBytes);
File.WriteAllText(Path.Combine(transferDir,"task.json"),"null");preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));Check(!preview.Complete,"unreadable transfer reference blocks all recycle");File.WriteAllText(Path.Combine(transferDir,"task.json"),JsonSerializer.Serialize(new{Path=transfer}));
var unknown=Path.Combine(root,"project-imports","unknown-user-note.txt");File.WriteAllText(unknown,"keep");preview=await ProjectStagingService.PreviewAsync(ProjectStagingService.Snapshot(store));Check(!preview.Complete&&File.ReadAllText(unknown)=="keep","unknown root-level files are counted conservatively and never removed");
Console.WriteLine("PASS total="+checks+" artifacts="+root);
